  {to_version:8,description:'H-07 (P&ID locator model): drawing, drawing_locator stores. H-08 (field observation layer): field_observation store. H-10 (retention/resolvability): no new store — retention_status/retained_until fields added to source_artifact records going forward; existing rows read with retention_status defaulting to ACTIVE via getArtifactRetentionStatus, not backfilled.',stores_added:['drawing','drawing_locator','field_observation'],stores_removed:[],breaking:false}
