 const make=(n,k)=>{if(!db.objectStoreNames.contains(n))db.createObjectStore(n,{keyPath:k});}; make('source','source_id');make('source_artifact','artifact_id');make('entity','entity_id');make('entity_identifier','entity_identifier_id');make('relationship','relationship_id');make('evidence','evidence_id');make('observation','observation_id');make('standard_mapping','mapping_id');make('change_event','event_id');make('decision','decision_id');make('drawing','drawing_id');make('drawing_locator','locator_id');make('field_observation','field_observation_id');
 const idx=(n,i,k,u=false)=>{const s=upgradeTx.objectStore(n);if(!s.indexNames.contains(i))s.createIndex(i,k,{unique:u});};
