async function updateEntity(id,p={},m={}){const db=await openDb();return runTransaction(db,['entity','change_event'],'readwrite',async tx=>{const s=tx.objectStore('entity'),old=await requestToPromise(s.get(id));if(!old)throw new Error(`entity_id "${id}" does not exist`);const e={...old},changed=[];for(const k of ['canonical_name','display_name','context','status'])if(p[k]!==undefined&&p[k]!==old[k]){e[k]=p[k];changed.push(k);}const manualOverride=m.manual_override!==false&&!m.source_id?changed.filter(k=>['canonical_name','display_name','context'].includes(k)):[];e.manual_override_fields=[...new Set([...(old.manual_override_fields||[]),...manualOverride])];e.updated_at=nowIso();await requestToPromise(s.put(e));appendChange(tx,{event_type:m.event_type||'ENTITY_UPDATED',subject_type:'entity',subject_id:id,entity_id:id,before_value:old,after_value:e,source_id:m.source_id,reason:m.reason,override_fields:manualOverride});return e;});}
