const normalizeForSearch=v=>String(v??'').toLowerCase().trim();
function searchEntities(es,o={}){let r=es,q=normalizeForSearch(o.query||'');if(q)r=r.filter(e=>['canonical_name','display_name','entity_id','entity_type'].some(k=>normalizeForSearch(e[k]).includes(q)));if(o.entity_type)r=r.filter(e=>e.entity_type===o.entity_type);if(o.status)r=r.filter(e=>e.status===o.status);if(o.contextLevels&&o.contextLevels.length>0){const want=o.contextLevels;r=r.filter(e=>{const lv=parseContextHierarchy(e.context).levels;if(lv.length<want.length)return false;return want.every((w,i)=>lv[i]===w);});}const by=o.sort_by||'updated_at',dir=o.sort_order||'desc';r=[...r].sort((a,b)=>{const c=String(a[by]??'').localeCompare(String(b[by]??''));return dir==='asc'?c:-c;});const total=r.length,ps=o.pageSize||20,tp=Math.max(1,Math.ceil(total/ps)),page=Math.min(Math.max(1,o.page||1),tp);return {items:r.slice((page-1)*ps,page*ps),total,page,pageSize:ps,totalPages:tp};}
